#!/usr/bin/env python3
"""Does the eg arm Read the file anyway, after search already handed it the complete body?

Reads the Claude Code transcripts for each recorded session_id and counts tool calls by name.
Zero API cost - pure post-hoc accounting of runs already on disk.
"""
import json, glob, os, sys, collections, statistics as st

RES = "/private/tmp/claude-501/-Users-suhaan-devenv/7e3deab1-a028-46d5-9bf1-3318de93a0b6/scratchpad/graphmark/agentic-swebench/results"
PROJ = os.path.expanduser("~/.claude/projects")

# session_id -> transcript path, built once
INDEX = {}
for f in glob.glob(PROJ + "/*/*.jsonl"):
    INDEX[os.path.basename(f)[:-6]] = f


def tools_for(sid):
    p = INDEX.get(sid)
    if not p:
        return None
    c = collections.Counter()
    try:
        for line in open(p, errors="replace"):
            try:
                d = json.loads(line)
            except Exception:
                continue
            msg = d.get("message") or {}
            cont = msg.get("content")
            if not isinstance(cont, list):
                continue
            for b in cont:
                if isinstance(b, dict) and b.get("type") == "tool_use":
                    name = b.get("name", "?")
                    c[name] += 1
                    if name == "Bash":
                        cmd = (b.get("input") or {}).get("command", "")
                        head = cmd.strip().split()[0] if cmd.strip() else ""
                        if "eg-q" in cmd or "cmm-q" in cmd:
                            c["_wrapper"] += 1
                        elif head in ("grep", "rg", "find", "ls", "cat", "head", "tail", "sed", "awk"):
                            c["_shell_explore"] += 1
    except Exception:
        return None
    return c


def run(tag):
    base = os.path.join(RES, tag)
    rows = []
    for f in sorted(glob.glob(base + "/*/*/cc_out.json")) + sorted(glob.glob(base + "/*/cc_out.json")):
        try:
            d = json.load(open(f))
        except Exception:
            continue
        sid = d.get("session_id")
        t = tools_for(sid) if sid else None
        rows.append({
            "iid": os.path.basename(os.path.dirname(f)),
            "turns": d.get("num_turns"), "usd": d.get("total_cost_usd"),
            "tools": t, "found": t is not None,
        })
    return rows


print(f"{'tag':<18} {'sess':>5} {'txcript':>8} {'turns':>6} {'USD':>8} "
      f"{'Read':>6} {'Edit':>6} {'Bash':>6} {'wrap':>6} {'shellexp':>9} {'Grep':>6}")
for tag in sys.argv[1:]:
    rows = run(tag)
    if not rows:
        print(f"{tag:<18} NO DATA")
        continue
    got = [r for r in rows if r["found"]]
    def m(key):
        v = [r["tools"].get(key, 0) for r in got]
        return st.mean(v) if v else float("nan")
    turns = [r["turns"] for r in rows if r["turns"] is not None]
    usd = [r["usd"] for r in rows if r["usd"] is not None]
    print(f"{tag:<18} {len(rows):>5} {len(got):>8} {st.mean(turns):>6.1f} {st.mean(usd):>8.4f} "
          f"{m('Read'):>6.2f} {m('Edit'):>6.2f} {m('Bash'):>6.2f} {m('_wrapper'):>6.2f} "
          f"{m('_shell_explore'):>9.2f} {m('Grep'):>6.2f}")

