#!/usr/bin/env python3
"""Blind-spot-free leak audit for a set of run tags.

The harness's own analysis/leakaudit/scan.py hardcodes an optional `(?:-C\\s+\\S+\\s+)?` prefix and
therefore CANNOT see `--no-pager`, `-c k=v`, `--git-dir=`, `--work-tree=`, `--exec-path=`, or an
absolute-path git. This scanner normalizes ANY sequence of leading git global options before
classifying the subcommand, so it sees every form the guard can be defeated with.

Classifies each Bash tool call in each session transcript:
  HISTORY  - reads content from beyond base_commit (log/show/blame/cat-file/rev-list/... , grep <ref>,
             diff <ref>, restore --source, format-patch, archive, ls-tree, for-each-ref, whatchanged)
  BYPASS   - a HISTORY subcommand invoked with leading global options (i.e. it evaded netjail)
  ABSPATH  - git invoked by absolute path or via env/PATH prefix (bypasses the shim entirely)
Usage: leakscan.py <tag/arm> [<tag/arm> ...]
"""
import json, glob, os, re, shlex, sys, collections

RES = "/private/tmp/claude-501/-Users-suhaan-devenv/7e3deab1-a028-46d5-9bf1-3318de93a0b6/scratchpad/graphmark/agentic-swebench/results"
PROJ = os.path.expanduser("~/.claude/projects")

HIST_SUBS = {
    "log", "show", "blame", "reflog", "cat-file", "rev-list", "describe", "format-patch",
    "archive", "ls-tree", "for-each-ref", "whatchanged", "range-diff", "merge-tree",
    "cherry", "patch-id", "notes", "stash", "bisect", "worktree", "submodule",
    "fetch", "pull", "clone", "checkout", "switch", "cherry-pick", "revert",
    "tag", "branch", "remote", "ls-remote", "verify-pack", "unpack-objects",
    "read-tree", "checkout-index",
}
# global options that take a separate value argument
GLOBAL_WITH_VAL = {"-C", "-c", "--git-dir", "--work-tree", "--exec-path", "--namespace",
                   "--super-prefix", "--config-env"}
GLOBAL_FLAG = {"--no-pager", "-p", "--paginate", "--bare", "--literal-pathspecs",
               "--no-replace-objects", "--no-optional-locks", "--glob-pathspecs",
               "--noglob-pathspecs", "--icase-pathspecs", "--no-lazy-fetch", "--html-path"}
REFISH = re.compile(r"^(HEAD([~^].*)?|origin/.*|refs/.*|.*\.\..*|[0-9a-f]{7,40})$")

INDEX = {}
for f in glob.glob(PROJ + "/*/*.jsonl"):
    INDEX[os.path.basename(f)[:-6]] = f


def split_git(tokens):
    """Return (globals_used, subcommand, rest) for a token list starting at a git word."""
    i, gl = 1, []
    while i < len(tokens):
        t = tokens[i]
        if t in GLOBAL_FLAG:
            gl.append(t); i += 1
        elif t in GLOBAL_WITH_VAL:
            gl.append(t); i += 2
        elif any(t.startswith(g + "=") for g in GLOBAL_WITH_VAL):
            gl.append(t.split("=")[0]); i += 1
        elif t.startswith("-c") and len(t) > 2:
            gl.append("-c"); i += 1
        elif t.startswith("-C") and len(t) > 2:
            gl.append("-C"); i += 1
        else:
            break
    return gl, (tokens[i] if i < len(tokens) else ""), tokens[i + 1:]


def classify(cmd):
    """Yield (kind, subcommand, globals, snippet) for every git invocation inside a shell string."""
    out = []
    # split on shell separators so `a && git log` is seen
    for piece in re.split(r"(?:&&|\|\||;|\||\n)", cmd):
        try:
            toks = shlex.split(piece.strip())
        except ValueError:
            toks = piece.strip().split()
        if not toks:
            continue
        # strip env assignments and `command`/`env` wrappers, remembering abspath
        abspath = False
        while toks and (re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", toks[0]) or toks[0] in ("command", "env", "eval", "nohup", "time")):
            if toks[0].startswith("PATH="):
                abspath = True
            toks = toks[1:]
        if not toks:
            continue
        exe = toks[0]
        base = os.path.basename(exe)
        if base != "git":
            continue
        if exe != "git":
            abspath = True
        gl, sub, rest = split_git(toks)
        kind = None
        if sub in HIST_SUBS:
            kind = "HISTORY"
        elif sub == "grep" and any(REFISH.match(a) for a in rest if not a.startswith("-")):
            kind = "HISTORY"
        elif sub == "diff":
            args = rest[:rest.index("--")] if "--" in rest else rest
            if any(REFISH.match(a) for a in args if not a.startswith("-")):
                kind = "HISTORY"
        elif sub == "restore" and any(a.startswith("--source") or a == "-s" for a in rest):
            kind = "HISTORY"
        if kind is None:
            continue
        if abspath:
            out.append(("ABSPATH", sub, gl, piece.strip()[:160]))
        elif gl:
            out.append(("BYPASS", sub, gl, piece.strip()[:160]))
        else:
            out.append(("BLOCKED_ATTEMPT", sub, gl, piece.strip()[:160]))
    return out


def main():
    print(f"{'tag/arm':<26} {'sess':>5} {'tx':>4} {'bypass':>7} {'abspath':>8} {'blockedtry':>11} {'sessions_leaked':>16}")
    for spec in sys.argv[1:]:
        tag, arm = spec.split("/")
        counts = collections.Counter()
        leaked = []
        n = tx = 0
        for f in sorted(glob.glob(f"{RES}/{tag}/{arm}/*/cc_out.json")):
            n += 1
            try:
                sid = json.load(open(f)).get("session_id")
            except Exception:
                continue
            p = INDEX.get(sid)
            if not p:
                continue
            tx += 1
            hit = []
            for line in open(p, errors="replace"):
                try:
                    d = json.loads(line)
                except Exception:
                    continue
                cont = (d.get("message") or {}).get("content")
                if not isinstance(cont, list):
                    continue
                for b in cont:
                    if isinstance(b, dict) and b.get("type") == "tool_use" and b.get("name") == "Bash":
                        for kind, sub, gl, snip in classify((b.get("input") or {}).get("command", "")):
                            counts[kind] += 1
                            if kind in ("BYPASS", "ABSPATH"):
                                hit.append((kind, sub, ",".join(gl), snip))
            if hit:
                leaked.append((os.path.basename(os.path.dirname(f)), hit))
        print(f"{spec:<26} {n:>5} {tx:>4} {counts['BYPASS']:>7} {counts['ABSPATH']:>8} "
              f"{counts['BLOCKED_ATTEMPT']:>11} {len(leaked):>16}")
        for iid, hits in leaked:
            print(f"    !! {iid}")
            for kind, sub, gl, snip in hits[:6]:
                print(f"       {kind} git[{gl}] {sub}: {snip}")


if __name__ == "__main__":
    main()

