#!/usr/bin/env python3
"""Is there a hard Read-before-Edit floor in this agent harness?

For every session: walk the transcript in order and check whether each Edit/Write on a file was
preceded by a Read of that same file. If Claude Code enforces read-before-edit, then
  (a) edits-without-prior-read == 0, and
  (b) reads can never fall below the number of DISTINCT files edited.
Also reports any tool_result that actually contains the enforcement error text.

Zero API cost. Usage: editfloor.py <tag/arm> [...]
"""
import json, glob, os, sys, collections

RES = "/private/tmp/claude-501/-Users-suhaan-devenv/7e3deab1-a028-46d5-9bf1-3318de93a0b6/scratchpad/graphmark/agentic-swebench/results"
PROJ = os.path.expanduser("~/.claude/projects")
INDEX = {}
for f in glob.glob(PROJ + "/*/*.jsonl"):
    INDEX[os.path.basename(f)[:-6]] = f

ERRTXT = ("has not been read yet", "Read it first", "must read the file", "before editing")


def walk(sid):
    p = INDEX.get(sid)
    if not p:
        return None
    read = set()
    edits = 0
    edits_unread = 0
    files_edited = set()
    reads = 0
    enforce_hits = 0
    for line in open(p, errors="replace"):
        try:
            d = json.loads(line)
        except Exception:
            continue
        cont = (d.get("message") or {}).get("content")
        if not isinstance(cont, list):
            continue
        for b in cont:
            if not isinstance(b, dict):
                continue
            if b.get("type") == "tool_use":
                nm = b.get("name")
                inp = b.get("input") or {}
                fp = inp.get("file_path") or ""
                if nm == "Read":
                    reads += 1
                    if fp:
                        read.add(fp)
                elif nm in ("Edit", "Write", "NotebookEdit", "MultiEdit"):
                    edits += 1
                    if fp:
                        files_edited.add(fp)
                        if fp not in read:
                            edits_unread += 1
            elif b.get("type") == "tool_result":
                c = b.get("content")
                txt = c if isinstance(c, str) else json.dumps(c)[:4000]
                if any(e in txt for e in ERRTXT):
                    enforce_hits += 1
    return dict(reads=reads, edits=edits, edits_unread=edits_unread,
                files_edited=len(files_edited), enforce=enforce_hits)


def main():
    print(f"{'tag/arm':<24} {'sess':>5} {'reads':>7} {'edits':>6} {'edits_wo_read':>14} "
          f"{'distinct_files_edited':>22} {'enforcement_errors':>19}")
    for spec in sys.argv[1:]:
        tag, arm = spec.split("/")
        agg = collections.Counter()
        n = 0
        for f in sorted(glob.glob(f"{RES}/{tag}/{arm}/*/cc_out.json")):
            try:
                sid = json.load(open(f)).get("session_id")
            except Exception:
                continue
            r = walk(sid)
            if not r:
                continue
            n += 1
            for k, v in r.items():
                agg[k] += v
        if not n:
            print(f"{spec:<24} NO DATA"); continue
        print(f"{spec:<24} {n:>5} {agg['reads']/n:>7.2f} {agg['edits']/n:>6.2f} "
              f"{agg['edits_unread']:>14} {agg['files_edited']/n:>22.2f} {agg['enforce']:>19}")


if __name__ == "__main__":
    main()

