#!/usr/bin/env python3
"""Split every eg Read into the fix that would remove it.

MANDATORY        - file was later Edited; Claude Code refuses Edit without a prior Read -> irreducible
REDUNDANT_EXPL   - complete body already in payload, file never edited -> EMITTER (trust/range)
PARTIAL_EXPL     - file in payload but only as a bodyless locator, never edited -> EMITTER (emit body)
ABSENT_EXPL      - file never in payload, never edited -> RECALL (ranking/coverage)

Emitter-addressable = REDUNDANT_EXPL + PARTIAL_EXPL. Recall-addressable = ABSENT_EXPL.
Zero API cost. Usage: readsplit.py <tag/arm> [...]
"""
import json, glob, os, re, sys, collections

RES = "/private/tmp/claude-501/-Users-suhaan-devenv/7e3deab1-a028-46d5-9bf1-3318de93a0b6/scratchpad/graphmark/agentic-swebench/results"
PROJ = os.path.expanduser("~/.claude/projects")
HIT = re.compile(r'^(\d+)\.\s+(\S+?):(\d[\d\-]*)\s*(.*)$')

INDEX = {}
for f in glob.glob(PROJ + "/*/*.jsonl"):
    INDEX[os.path.basename(f)[:-6]] = f


def payload(path):
    allf, comp = set(), set()
    if not os.path.exists(path):
        return allf, comp
    for line in open(path, errors="replace"):
        m = HIT.match(line)
        if m:
            allf.add(m.group(2))
            if "complete-symbol" in m.group(4):
                comp.add(m.group(2))
    return allf, comp


def walk(sid, wt):
    """-> (reads[list of (path, had_range)], edited{paths})"""
    p = INDEX.get(sid)
    reads, edited = [], set()
    if not p:
        return reads, edited
    for line in open(p, errors="replace"):
        try:
            d = json.loads(line)
        except Exception:
            continue
        c = (d.get("message") or {}).get("content")
        if not isinstance(c, list):
            continue
        for b in c:
            if not isinstance(b, dict) or b.get("type") != "tool_use":
                continue
            inp = b.get("input") or {}
            fp = inp.get("file_path") or ""
            if wt and fp.startswith(wt):
                fp = fp[len(wt):].lstrip("/")
            if b.get("name") == "Read":
                reads.append((fp, ("offset" in inp or "limit" in inp)))
            elif b.get("name") in ("Edit", "Write", "MultiEdit", "NotebookEdit"):
                if fp:
                    edited.add(fp)
    return reads, edited


def main():
    for spec in sys.argv[1:]:
        tag, arm = spec.split("/")
        c = collections.Counter()
        n = 0
        unbounded = 0
        for f in sorted(glob.glob(f"{RES}/{tag}/{arm}/*/cc_out.json")):
            iid = os.path.basename(os.path.dirname(f))
            try:
                sid = json.load(open(f)).get("session_id")
            except Exception:
                continue
            allf, comp = payload(os.path.join(os.path.dirname(f), "gq_calls.log.payload"))
            wt = f"/private/tmp/claude-501/-Users-suhaan-devenv/7e3deab1-a028-46d5-9bf1-3318de93a0b6/scratchpad/graphmark/agentic-swebench/checkouts/{tag}/{arm}/{iid}"
            reads, edited = walk(sid, wt)
            if not reads:
                continue
            n += 1
            for fp, ranged in reads:
                if not ranged:
                    unbounded += 1
                if fp in edited:
                    c["MANDATORY"] += 1
                elif fp in comp:
                    c["REDUNDANT_EXPL"] += 1
                elif fp in allf:
                    c["PARTIAL_EXPL"] += 1
                else:
                    c["ABSENT_EXPL"] += 1
        tot = sum(c[k] for k in ("MANDATORY", "REDUNDANT_EXPL", "PARTIAL_EXPL", "ABSENT_EXPL"))
        emit = c["REDUNDANT_EXPL"] + c["PARTIAL_EXPL"]
        rec = c["ABSENT_EXPL"]
        rem = emit + rec
        print(f"\n{spec}  sessions={n}  reads={tot}  ({tot/max(n,1):.2f}/session)  unbounded(no offset/limit)={unbounded}")
        for k in ("MANDATORY", "REDUNDANT_EXPL", "PARTIAL_EXPL", "ABSENT_EXPL"):
            print(f"   {k:<16} {c[k]:5}  {100*c[k]/max(tot,1):5.1f}%   {c[k]/max(n,1):5.2f}/session")
        print(f"   -> removable       {rem:5}  {rem/max(n,1):5.2f}/session")
        print(f"   -> EMITTER-fixable {emit:5}  {100*emit/max(rem,1):5.1f}% of removable   {emit/max(n,1):5.2f}/session")
        print(f"   -> RECALL-fixable  {rec:5}  {100*rec/max(rem,1):5.1f}% of removable   {rec/max(n,1):5.2f}/session")


if __name__ == "__main__":
    main()

