// searchVerifyTestEvidence builds an evidence view over a fixed set of repository files. The runner
// probe is satisfied unconditionally: these tests are about DERIVATION, and letting them resolve
// against the real PATH would make them pass or fail on whether the test machine happens to have
// maven or php installed. searchVerifyTestEvidenceWithout states the runners a machine lacks.
func searchVerifyTestEvidence(files map[string]string) searchVerifyEvidence {
	return searchVerifyTestEvidenceWithout(files)
}

// searchVerifyTestEvidenceWithout builds the same view, but reports the named executables as absent
// from PATH so the probe can be exercised deterministically.
func searchVerifyTestEvidenceWithout(files map[string]string, missing ...string) searchVerifyEvidence {
	absent := make(map[string]bool, len(missing))
	for _, name := range missing {
		absent[name] = true
	}
	return searchVerifyEvidence{
		read: func(path string) (string, bool) {
			content, ok := files[path]
			return content, ok
		},
		lookPath: func(name string) (string, error) {
			if absent[name] {
				return "", exec.ErrNotFound
			}
			return "/usr/bin/" + name, nil
		},
	}
}

