func TestBuildSearchVerifyCommandStaysSilentWhenTheRunnerIsAbsent(t *testing.T) {
	t.Parallel()
	files := map[string]string{
		"go.mod":               "module x\n",
		"internal/a/a.go":      "package a\n",
		"internal/a/a_test.go": "package a\n\nfunc TestDispatch(t *testing.T) {}\n",
	}
