		{Rank: 2, FilePath: "internal/a/a_test.go", Section: searchSectionPrimary},
	}
	present := searchVerifyTestEvidenceWithout(files)
	if got := buildSearchVerifyCommand(results, present); got == nil {
		t.Fatal("expected a command when the runner is on PATH")
	}
	absent := searchVerifyTestEvidenceWithout(files, "go")
	if got := buildSearchVerifyCommand(results, absent); got != nil {
		t.Fatalf("expected silence when `go` is not installed, got %q", got.Command)
	}
}

// The runner is whatever the command actually execs, which is not the first word when the derivation
// prefixed a `cd` to reach a manifest that is not at the repository root.
func TestSearchVerifyRunnerSkipsCdPrefixes(t *testing.T) {
	t.Parallel()
	for _, tc := range []struct{ command, want string }{
		{"go test ./internal/a -run '^TestX$'", "go"},
		{"cd fuzz && cargo test", "cargo"},
		{"cd packages/core && npx jest src/a.test.ts", "npx"},
		{"bundle exec rspec spec/a_spec.rb", "bundle"},
		{"php -l src/A.php", "php"},
		{"vendor/bin/phpunit --filter A", "vendor/bin/phpunit"},
		{"./gradlew :app:test", "./gradlew"},
		{"cd a && cd b && make check", "make"},
		{"", ""},
		{"cd nowhere-without-separator", ""},
	} {
