input.new_string:
	// `flows` is a map, so the drain above is in random order. Ordering by
	// (Name, EvidenceKind) alone leaves ties between entries that differ ONLY in
	// Detail — two parameters of the same caller forwarded into the same callee,
	// e.g. loadSpecs(manifestPath, limit) yields both "manifestPath -> loadSpecs()"
	// and "limit -> loadSpecs()" under kind argument_forward_flow. sort.Slice is not
	// stable, so those tied entries came out in the map's random order. The provider
	// then dedups relations on (FromID, ToID, Type) — Detail is deliberately NOT in
	// that key — so whichever tied flow was emitted first won, and the surviving
	// evidence.detail changed between runs on an identical tree. Measured on this
	// repo: 157 of 33,998 records differed across two runs, same identities, evidence
	// the only differing field. Detail is the map key's third component, so adding it
	// here makes the order total and the snapshot byte-reproducible.
	sort.Slice(out, func(i, j int) bool {
		if out[i].Name != out[j].Name {
			return out[i].Name < out[j].Name
		}
		if out[i].EvidenceKind != out[j].EvidenceKind {
			return out[i].EvidenceKind < out[j].EvidenceKind
		}
		return out[i].Detail < out[j].Detail
	})
	return out
}

