// sort.Slice is not stable, so tied entries inherited Go's randomized map order.
// Go re-randomizes per range, so repeating the call in one process is enough to
// catch it.
func TestReturnFlowCallsOrderIsDeterministicForTiedDetails(t *testing.T) {
	t.Parallel()
	// Both parameters are forwarded into the SAME callee, so the two flows share
	// Name and EvidenceKind and differ only in Detail.
	block := `func run(manifestPath string, limit int) []Spec {
	return loadSpecs(manifestPath, limit)
}`
	params := map[string]bool{"manifestPath": true, "limit": true}

	want := returnFlowCalls(block, params)
	var tied int
	for i := 1; i < len(want); i++ {
		if want[i-1].Name == want[i].Name && want[i-1].EvidenceKind == want[i].EvidenceKind {
			tied++
		}
	}
	if tied == 0 {
		t.Fatalf("fixture no longer produces flows tied on (Name, EvidenceKind); it cannot detect the defect: %#v", want)
	}
	for i := 0; i < 200; i++ {
		got := returnFlowCalls(block, params)
		if len(got) != len(want) {
			t.Fatalf("iteration %d: length changed %d -> %d", i, len(want), len(got))
		}
		for j := range got {
			if got[j] != want[j] {
				t.Fatalf("iteration %d: order changed at %d:\n first: %#v\n now:   %#v", i, j, want[j], got[j])
			}
		}
	}
}

// End-to-end guard: the same tree must serialize to the same bytes. The unit test
// above pins the ordering; this pins the property the ordering exists for, and is
// what AGENTS.md promises ("the same commit always yields the same graph").
func TestBuildProviderSnapshotRelationEvidenceIsReproducible(t *testing.T) {
	t.Parallel()
	repo := t.TempDir()
	writeFile(t, repo, "flow.go", `package flow

func loadSpecs(manifestPath string, limit int) []string { return nil }

func runGit(ctx string, ref string) string { return ref }

func run(manifestPath string, limit int) []string {
	return loadSpecs(manifestPath, limit)
}

func gitRun(ctx string, ref string) string {
	return runGit(ctx, ref)
}
`)

	render := func() string {
		snapshot, err := BuildProviderSnapshot(context.Background(), repo, "test-version")
		if err != nil {
			t.Fatal(err)
		}
		var flows []RelationRecord
		for _, relation := range snapshot.Relations {
			if relation.Type == "DATA_FLOWS" {
				flows = append(flows, relation)
			}
		}
		if len(flows) == 0 {
			t.Fatal("fixture produced no DATA_FLOWS; it cannot detect the defect")
		}
		out, err := json.Marshal(flows)
		if err != nil {
			t.Fatal(err)
		}
		return string(out)
	}

	first := render()
	for i := 0; i < 5; i++ {
		if got := render(); got != first {
			t.Fatalf("snapshot %d differs from the first on an identical tree:\n first: %s\n now:   %s", i, first, got)
		}
	}
}

