#!/usr/bin/env python3
"""Does the graph's ONE search actually land on the file the gold patch edits?

This separates the two possible causes of the ~7 greps that follow every search:
  (a) retrieval MISS -- the payload never named the gold file, so the greps are forced. Fixing
      that is tool work on the ranker.
  (b) retrieval HIT but the agent greps anyway -- the payload named the right file and the agent
      still went looking. Then the problem is that the payload does not carry enough to act on,
      or the agent will not act on it, and more ranking accuracy buys nothing.

Reported per model and split HIT/MISS: greps-after-search, turns, and the usd ratio vs the
paired baseline session. If (a) dominates, the two groups separate sharply on all three.
"""
import json, os, glob, re, math, statistics, collections

AS = '/private/tmp/claude-501/-Users-suhaan-devenv/7e3deab1-a028-46d5-9bf1-3318de93a0b6/scratchpad/graphmark/agentic-swebench'
HOME = os.path.expanduser('~')
IDX = {os.path.basename(p)[:-6]: p for p in glob.glob(f'{HOME}/.claude/projects/*/*.jsonl')}
TASKS = {t['instance_id']: t for t in json.load(open(f'{AS}/tasks/rep30_tasks.json'))['instances']}

def gold_files(iid):
    pat = TASKS[iid]['patch']
    return {m for m in re.findall(r'^diff --git a/(\S+) b/\S+', pat, re.M)}

def first_payload(sid):
    """the tool_result text for the FIRST eg-q.run search call, plus greps issued afterwards"""
    p = IDX.get(sid)
    if not p: return None, 0, 0
    pend, payload, greps, total_after = None, None, 0, 0
    for line in open(p, errors='replace'):
        try: j = json.loads(line)
        except Exception: continue
        if j.get('type') == 'assistant':
            for c in (j.get('message') or {}).get('content') or []:
                if not (isinstance(c, dict) and c.get('type') == 'tool_use'): continue
                cmd = (c.get('input') or {}).get('command') or ''
                if payload is None and pend is None and 'eg-q.run' in cmd and ' search' in cmd:
                    pend = c.get('id')
                elif payload is not None:
                    total_after += 1
                    if c.get('name') in ('Grep', 'Glob') or re.search(r'\b(grep|rg|find|ls|cat|head|sed)\b', cmd):
                        greps += 1
        elif j.get('type') == 'user' and pend:
            for c in (j.get('message') or {}).get('content') or []:
                if isinstance(c, dict) and c.get('type') == 'tool_result' and c.get('tool_use_id') == pend:
                    cc = c.get('content')
                    payload = cc if isinstance(cc, str) else json.dumps(cc)
                    pend = None
    return payload, greps, total_after

def cellusd(tag, arm):
    out = {}
    for p in glob.glob(f'{AS}/results/{tag}/{arm}/*/cc_out.json'):
        iid = p.split('/')[-2]; j = json.load(open(p))
        pd = f'{AS}/results/{tag}/{arm}/{iid}/patch.diff'
        out[iid] = dict(usd=j.get('total_cost_usd') or 0, turns=j.get('num_turns') or 0,
                        sid=j.get('session_id'),
                        ok=(j.get('total_cost_usd') or 0) > 0 and os.path.exists(pd) and os.path.getsize(pd) > 0)
    return out

def run(name, btag, etag):
    B, E = cellusd(btag, 'baseline'), cellusd(etag, 'eg')
    rows = []
    for iid in sorted(set(B) & set(E)):
        if not (B[iid]['ok'] and E[iid]['ok']): continue
        gf = gold_files(iid)
        pay, greps, after = first_payload(E[iid]['sid'])
        if pay is None:
            rows.append((iid, None, greps, after, E[iid], B[iid], 0)); continue
        # HIT = payload text mentions any gold file path (basename match is too loose: a
        # same-named file in another package would score as a hit)
        hit = any(g in pay for g in gf)
        base_hit = any(os.path.basename(g) in pay for g in gf)
        rows.append((iid, hit, greps, after, E[iid], B[iid], len(pay), base_hit, gf))
    print(f'\n=== {name}  n={len(rows)}')
    for label, sel in (('HIT (gold path in payload)', lambda r: r[1] is True),
                       ('MISS', lambda r: r[1] is False),
                       ('no payload captured', lambda r: r[1] is None)):
        sub = [r for r in rows if sel(r)]
        if not sub: print(f'  {label:28} n=0'); continue
        g = statistics.mean(r[2] for r in sub)
        t = statistics.mean(r[4]['turns'] for r in sub)
        bt = statistics.mean(r[5]['turns'] for r in sub)
        ratio = math.exp(statistics.mean(math.log(r[4]['usd'] / r[5]['usd']) for r in sub)) - 1
        print(f'  {label:28} n={len(sub):2}  greps_after={g:5.2f}  egTurns={t:5.1f} baseTurns={bt:5.1f}  usd geomean={100*ratio:+6.1f}%')
    print(f'  {"instance":34} {"hit":5} {"base?":5} {"greps":>5} {"egT":>4} {"bT":>4} {"usd%":>7}  payload_chars')
    for r in sorted(rows, key=lambda r: -(r[4]['usd'] / r[5]['usd'])):
        if r[1] is None:
            print(f'  {r[0]:34} {"n/a":5} {"":5} {r[2]:5} {r[4]["turns"]:4} {r[5]["turns"]:4} '
                  f'{100*(r[4]["usd"]/r[5]["usd"]-1):+6.1f}%  -')
        else:
            print(f'  {r[0]:34} {str(r[1]):5} {str(r[7]):5} {r[2]:5} {r[4]["turns"]:4} {r[5]["turns"]:4} '
                  f'{100*(r[4]["usd"]/r[5]["usd"]-1):+6.1f}%  {r[6]}')
    return rows

if __name__ == '__main__':
    run('SONNET post-fix', 'R30SbaseF', 'R30SegF')
    run('HAIKU  post-fix', 'R30HbaseF', 'R30HegF')

