func codeLikeSearchWeight(raw string) float64 {
	trimmed := strings.Trim(raw, "./:+-")
	letters := 0
	digits := 0
	allUpper := true
	for _, character := range trimmed {
		if unicode.IsDigit(character) {
			digits++
			continue
		}
		if !unicode.IsLetter(character) {
			continue
		}
		letters++
		if unicode.IsLower(character) {
			allUpper = false
		}
	}
	// The 1.4 branch exists to stop a short ALL-CAPS English acronym (API, URL, SQL, HTTP) from
	// being scored as if the user had typed an identifier. Digits were skipped by the loop above
	// and so never counted against `letters`, which meant an alphanumeric CODE — a lint rule id,
	// an error code, an opcode, a register or status name — took the acronym branch too:
	// "SIM201" has three letters, so it scored 1.4.
	//
	// That is not a cosmetic misclassification. The exact-code-token bonus is gated on
	// `q.weights[term] >= 2` (see scoreSearchCandidates), so at 1.4 the file that literally
	// DEFINES the code the query quotes earns none of that +6*weight (cap 24) and a smaller idf
	// multiplier — it loses to files that merely share prose. Measured: on astral-sh__ruff-15626
	// ("SIM201 and SIM202 fixes should be marked as unsafe"), the gold file is the only file in
	// the repo containing those literals and was not retrieved at ANY top-k up to 30.
	//
	// A token carrying digits is therefore never an acronym: require the token to be all letters
	// before taking the demotion.
	if allUpper && digits == 0 && letters > 0 && letters <= 4 {
		return 1.4
	}
	return 2.5
}

