#!/usr/bin/env python3
"""Append, under each bodied search hit, the in-repo symbols that hit's body CALLS.

WHY (measured, adversarially verified on two instances):

The payload prints a symbol's complete body and then never resolves the identifiers inside it,
even though the CALLS edge is already sitting in graph.edges.ndjson.

  vuejs__core-11870 — rank-1 body contains `source = shallowReadArray(source)`. The 4 lines of
  shallowReadArray (`track((arr = toRaw(arr)), ...)`) are what make the obvious fix a no-op: it
  strips the shallow flag, so testing `isShallow(source)` after that line always reads false. eg
  made the wrong edit, burned ~8 turns on repro/rebuild loops, and at turn 33 ran
  `eg-q def shallowReadArray`, immediately said "I see the issue!", and wrote the correct fix.
  The BASELINE got it right on its first edit because its "wasteful" grep sweep had read that
  callee for free at turn 9. The tool deleted the navigational turns and the load-bearing one.

  faker-ruby__faker-2970 — six consecutive turns (T3-T8) hunting `Char.prepare`, an identifier
  printed inside the payload's own hits #3 and #4, ending in a whole-filesystem
  `find / -iname char.rb`. The agent guessed `lib/faker/default/char.rb`; the real definition is
  `module Char` / `def self.prepare` elsewhere, so its greps for `def prepare` / `class Char`
  both returned nothing.

Bytes are free here: cost is ~95% cache_read, i.e. turns x context, and payload size is measured
NOT to correlate with cost (r = -0.10 Sonnet, -0.20 Haiku, both slightly favouring bigger). Turns
are the only currency, so trading bytes for turns is the whole point.

SELECTION, in priority order, capped so this can never dominate the payload:
  1. the call must actually appear in the emitted body (not merely be a graph edge),
  2. reassignment calls first (`x = f(x)`) — those are the semantics-changing ones that make a
     naive edit wrong, which is exactly the vuejs failure,
  3. in-repo definitions only, tests excluded,
  4. body inlined only when short; otherwise a locator line, which still kills the hunt.

Env: EG_CALLEES=<max callees overall, 0/unset = off>, EG_CALLEE_MAXLINES (default 12),
     GSYM / GEDGES / WT as already exported by the eg-q wrapper.
"""
import json, os, re, sys

MAX = int(os.environ.get('EG_CALLEES', '0') or 0)
MAXLINES = int(os.environ.get('EG_CALLEE_MAXLINES', '12') or 12)
GSYM = os.environ.get('GSYM', '')
GEDGES = os.environ.get('GEDGES', '')
WT = os.environ.get('WT', '')

TEST_RX = re.compile(r'(^|/)tests?/|_test\b|Test\.|\.test\.|(^|/)spec/|_spec\.|__tests__', re.I)
HDR = re.compile(r'^(\d+)\.\s+(\S+?):(\d+)(?:-(\d+))?(.*)$')


def load():
    """symbol id -> record, plus CALLS adjacency. One pass each; no model spend, no network."""
    byid, byname = {}, {}
    if not (GSYM and os.path.exists(GSYM)):
        return None, None, None
    for line in open(GSYM, errors='replace'):
        i = line.find('{')
        if i < 0:
            continue
        try:
            d = json.loads(line[i:])
        except Exception:
            continue
        if d.get('record_type') != 'symbol':
            continue
        byid[d['id']] = d
        for key in (d.get('qualified_name'), d.get('name')):
            if key:
                byname.setdefault(key, []).append(d)
    calls = {}
    if GEDGES and os.path.exists(GEDGES):
        for line in open(GEDGES, errors='replace'):
            if '"CALLS"' not in line:
                continue
            i = line.find('{')
            if i < 0:
                continue
            try:
                d = json.loads(line[i:])
            except Exception:
                continue
            if d.get('type') not in ('CALLS', 'ASYNC_CALLS'):
                continue
            calls.setdefault(d.get('from_id'), []).append(d.get('to_id'))
    return byid, byname, calls


def body_of(rec):
    p = os.path.join(WT, rec.get('file_path', ''))
    s, e = rec.get('start_line', 1), rec.get('end_line', rec.get('start_line', 1))
    if not os.path.exists(p) or (e - s + 1) > MAXLINES:
        return None
    try:
        lines = open(p, errors='replace').read().splitlines()
    except Exception:
        return None
    return '\n'.join(lines[s - 1:e])


def main():
    text = sys.stdin.read()
    if MAX <= 0:
        sys.stdout.write(text)
        return
    byid, byname, calls = load()
    if byid is None:
        sys.stdout.write(text)
        return

    lines = text.splitlines(keepends=True)
    # locate hits and the extent of each hit's printed body
    hits = []
    for idx, ln in enumerate(lines):
        m = HDR.match(ln)
        if m and int(m.group(1)) <= 60:
            hits.append(dict(idx=idx, path=m.group(2), meta=m.group(5) or ''))
    for n, h in enumerate(hits):
        end = hits[n + 1]['idx'] if n + 1 < len(hits) else len(lines)
        h['body'] = ''.join(lines[h['idx'] + 1:end])
        sm = re.search(r'symbol=(\S+)', h['meta'])
        h['symbol'] = sm.group(1) if sm else None

    emitted, out_blocks, budget = set(), {}, MAX
    for h in hits:
        if budget <= 0 or not h['symbol'] or not h['body'].strip():
            continue
        cands = [r for r in byname.get(h['symbol'], []) if r.get('file_path') == h['path']] \
            or byname.get(h['symbol'], [])
        if not cands:
            continue
        targets = []
        for tid in calls.get(cands[0]['id'], []):
            t = byid.get(tid)
            if not t or TEST_RX.search(t.get('file_path', '')):
                continue
            nm = t.get('name') or ''
            # the call must be visible in the body we actually printed
            if not nm or not re.search(r'\b' + re.escape(nm) + r'\s*\(', h['body']):
                continue
            key = (t.get('file_path'), t.get('start_line'))
            if key in emitted:
                continue
            # a reassignment call (x = f(x)) is the semantics-changing kind -- rank it first
            reassign = bool(re.search(r'(\w+)\s*=\s*[\w.]*\b' + re.escape(nm) + r'\s*\(\s*\1\b', h['body']))
            targets.append((0 if reassign else 1, t))
        if not targets:
            continue
        targets.sort(key=lambda x: x[0])
        block = []
        for _, t in targets:
            if budget <= 0:
                break
            emitted.add((t.get('file_path'), t.get('start_line')))
            budget -= 1
            head = f"  {t['file_path']}:{t.get('start_line')} {t.get('kind','')} {t.get('qualified_name') or t.get('name')}"
            b = body_of(t)
            block.append(head + ('\n' + '\n'.join('    ' + x for x in b.splitlines()) if b else ''))
        if block:
            out_blocks[h['idx']] = "CALLS (defined in this repo, from the body above):\n" + '\n'.join(block) + '\n'

    if not out_blocks:
        sys.stdout.write(text)
        return
    res, order = [], sorted(out_blocks)
    nxt = {h['idx']: (hits[n + 1]['idx'] if n + 1 < len(hits) else len(lines))
           for n, h in enumerate(hits)}
    insert_at = {nxt[i]: out_blocks[i] for i in order}
    for i, ln in enumerate(lines):
        if i in insert_at:
            res.append(insert_at[i])
        res.append(ln)
    if len(lines) in insert_at:
        res.append(insert_at[len(lines)])
    sys.stdout.write(''.join(res))


if __name__ == '__main__':
    main()

