// searchVerifyRankedTestRelated reports whether a test file that merely RANKED may stand in as the
// subject's test.
//
// The distinction this restores is between a test that was DERIVED and one that was merely NEARBY in
// the ranking. The covering-test section names the test that exercises hit 1; a ranked test is only
// "a test file the same query also matched", and accepting one unconditionally let a payload whose
// fix site was `pylint/lint/pylinter.py` emit
//
//	VERIFY: python -m pytest tests/config/test_find_default_config_files.py -k test_non_existent_home
//
// — a well-formed command, correctly derived from the manifest, for an unrelated module. VERIFY's
// contract is "how do I exercise the file I am changing", and this answered a different question with
// full confidence. Measured on that session: the agent spent messages 28-41 trying to install a
// toolchain for it, built six reproduction trees, and made its first edit at message 46 of 50,
// against the no-tool baseline's message 4 of 14.
//
// Relatedness is decided from path evidence only, never inference:
//
//   - the two files share a stem once test decoration is removed (`a.go` / `a_test.go`,
//     `Foo.php` / `FooTest.php`) — the same mirror-name convention searchVerifyMirrorTest encodes; or
//   - the test lives in the source's own directory, i.e. the same package or module.
//
// Anything else leaves testPath empty, and the mirror lookup plus the build check in
// buildSearchVerifyCommand take over. That is the intended degradation: `php -l <the file I edited>`
// is a weaker command than a named test case, but it is a command about the right file, and a wrong
// command costs strictly more than a narrow one — which is the same reasoning that makes silence the
// default everywhere else in this derivation.
func searchVerifyRankedTestRelated(sourcePath, testPath string) bool {
	if sourcePath == "" || testPath == "" || sourcePath == testPath {
		return false
	}
	if path.Dir(sourcePath) == path.Dir(testPath) {
		return true
	}
	sourceStem := searchVerifyBareStem(searchVerifyStem(path.Base(sourcePath)))
	testStem := searchVerifyBareStem(searchVerifyStem(path.Base(testPath)))
	return sourceStem != "" && sourceStem == testStem
}

// searchVerifyBareStem strips the conventional test decoration off a file stem so that `a_test`,
// `test_a`, `aTest` and `a` all reduce to `a`. Case-insensitive, because the affix conventions in
// searchVerifyTestAffixes span languages that disagree about it.
func searchVerifyBareStem(stem string) string {
	bare := strings.ToLower(stem)
	for _, affix := range searchVerifyTestAffixes {
		lowered := strings.ToLower(affix)
		bare = strings.TrimSuffix(bare, lowered)
		bare = strings.TrimPrefix(bare, lowered)
	}
	for _, prefix := range []string{"test_", "test-", "spec_", "spec-"} {
		bare = strings.TrimPrefix(bare, prefix)
	}
	for _, suffix := range []string{"_tests", "-tests", "_specs", "-specs", "_test", "-test", "_spec", "-spec"} {
		bare = strings.TrimSuffix(bare, suffix)
	}
	return strings.Trim(bare, "_-.")
}

