#!/usr/bin/env python3
"""Expose entire-graph's verbs as NATIVE MCP tools instead of a shell string.

WHY. Measured across the ten losing Sonnet repos: the graph is called 1.0 times per session and the
shell 9.3 times, and 58% of those shell searches ask a question a graph verb already answers
(immutable-js 100%, laravel 93%, vuejs 89%, bat 83%). Every losing repo calls the graph exactly once
-- the mandated first search -- then never again across a 16->26 turn session. `explain`, built for
the post-edit error phase, is invoked 2 times in 120 sessions while 20/20 losing sessions hit an error.

Telling the agent to use the verbs is REFUTED three times (one prompt line naming `def` moved a cell
-0.6% -> +14.9%). What has never been tried is changing how the tool is EXPOSED: today the graph is a
shell script the agent must remember to invoke *inside* the Bash tool, competing directly with grep,
where the model's prior is overwhelming. Native tools live in the tool list and get called.

This is a thin stdio shim over the same binary -- identical payloads, identical flags -- so any
difference it produces is attributable to exposure alone, not to content.
"""
import json, os, subprocess, sys

EG   = os.environ.get("EG", "")
REPO = os.environ.get("WT", ".")
CACHE= os.environ.get("CACHE", "/tmp/egq")
PROF = os.environ.get("EG_PROFILE", "full")
TOPK = os.environ.get("EG_TOPK", "12")
MAXB = os.environ.get("EG_MAXBYTES", "24576")
GQLOG= os.environ.get("GQLOG", "")

def log(verb, arg):
    if GQLOG:
        try:
            with open(GQLOG, "a") as f: f.write(f"{verb} {arg}\n")
        except Exception: pass

def run(args, timeout=600):
    try:
        r = subprocess.run([EG] + args, capture_output=True, text=True, timeout=timeout)
        return (r.stdout or "") + (("\n" + r.stderr) if r.returncode and r.stderr else "")
    except Exception as e:
        return f"error: {e}"

TOOLS = [
 {"name":"graph_search","description":
  "Find the code for a task. Ranked source regions for a plain-language description, with file:line "
  "and the complete body of the top hits inline. Use this FIRST for any locate question, before grep.",
  "inputSchema":{"type":"object","required":["query"],"properties":{
    "query":{"type":"string","description":"the bug or task in one sentence"}}}},
 {"name":"graph_def","description":
  "Where is this symbol declared, and what is its shape? Returns the declaration with its source, "
  "fields and member signatures. Matches the SYMBOL, not the text, so it works when you do not know "
  "how the declaration is spelled. Use instead of grepping for `def X` / `class X` / `func X`.",
  "inputSchema":{"type":"object","required":["symbol"],"properties":{
    "symbol":{"type":"string","description":"symbol name, e.g. RepairQueue or Foo.bar"}}}},
 {"name":"graph_callers","description":
  "Who calls this symbol, reported at the call site with the surrounding conditions. Use instead of "
  "grepping for usages.",
  "inputSchema":{"type":"object","required":["symbol"],"properties":{
    "symbol":{"type":"string"}}}},
 {"name":"graph_impact","description":
  "One-shot blast radius for changing a symbol: callers, callees, type consumers, data flows, "
  "co-change files, siblings. Use before finishing to find the other sites needing the same change.",
  "inputSchema":{"type":"object","required":["symbol"],"properties":{
    "symbol":{"type":"string"}}}},
 {"name":"graph_explain","description":
  "Decode a failing build or test. Paste the error output; returns the declaration of every symbol "
  "the error names, resolved against the working tree so it reflects the edit you just made. Use "
  "this instead of hunting for a toolchain or grepping an error message.",
  "inputSchema":{"type":"object","required":["output"],"properties":{
    "output":{"type":"string","description":"the build/test output, verbatim"}}}},
]

def call(name, a):
    if name == "graph_search":
        q = a.get("query",""); log("search", q)
        return run(["search","--query",q,"--repo",REPO,"--profile",PROF,"--format","text",
                    "--top-k",TOPK,"--max-context-bytes",MAXB,"--cache-dir",CACHE])
    if name == "graph_def":
        s = a.get("symbol",""); log("def", s)
        return run(["def","--repo",REPO,s,"--format","text"])
    if name == "graph_callers":
        s = a.get("symbol",""); log("callers", s)
        return run(["neighbors","--repo",REPO,"--symbol",s,"--relation","CALLS",
                    "--direction","in","--format","text"])
    if name == "graph_impact":
        s = a.get("symbol",""); log("impact", s)
        return run(["impact","--repo",REPO,"--symbol",s,"--format","text"])
    if name == "graph_explain":
        out = a.get("output",""); log("explain", out[:60].replace("\n"," "))
        try:
            r = subprocess.run([EG,"explain","--repo",REPO], input=out,
                               capture_output=True, text=True, timeout=300)
            return r.stdout or r.stderr or "(no symbols resolved)"
        except Exception as e:
            return f"error: {e}"
    return f"unknown tool {name}"

def send(o):
    sys.stdout.write(json.dumps(o) + "\n"); sys.stdout.flush()

for line in sys.stdin:
    line = line.strip()
    if not line: continue
    try: req = json.loads(line)
    except Exception: continue
    mid, m = req.get("id"), req.get("method")
    if m == "initialize":
        send({"jsonrpc":"2.0","id":mid,"result":{
            "protocolVersion":"2024-11-05","capabilities":{"tools":{}},
            "serverInfo":{"name":"entire-graph","version":"1"}}})
    elif m == "tools/list":
        send({"jsonrpc":"2.0","id":mid,"result":{"tools":TOOLS}})
    elif m == "tools/call":
        p = req.get("params",{})
        txt = call(p.get("name",""), p.get("arguments",{}) or {})
        send({"jsonrpc":"2.0","id":mid,"result":{"content":[{"type":"text","text":txt}]}})
    elif mid is not None:
        send({"jsonrpc":"2.0","id":mid,"result":{}})
