// searchNameIDFNormKey stores the normalizer inside the same map, so the coverage function keeps a
// single dependency. It is not a term: the space guarantees it cannot collide with one.
const searchNameIDFNormKey = " norm"

// searchNameTermIDF scores each query term by how rare it is among the CANDIDATE SYMBOL NAMES, and
// carries its own normalizer under searchNameIDFNormKey.
//
// df is counted over names, not files, because that is the corpus the coverage question is asked
// against. A term no name contains (df==0) is omitted entirely — that is what keeps issue prose out
// of the denominator, which was the sound half of the original "not idf-weighted" reasoning.
//
// The normalizer is the sum of the three largest weights among terms that some name DOES contain,
// matching the previous cap of three: a name carrying the three rarest available domain terms scores
// a full 1.0 exactly as it used to, so searchNameCoverageWeight keeps its measured calibration.
func searchNameTermIDF(candidates []searchCandidate, q searchQuery) map[string]float64 {
	if len(candidates) == 0 || len(q.terms) == 0 {
		return nil
	}
	df := make(map[string]int, len(q.terms))
	for i := range candidates {
		name := strings.ToLower(candidates[i].result.QualifiedName)
		if name == "" {
			name = strings.ToLower(candidates[i].result.SymbolName)
		}
		if name == "" {
			continue
		}
		for _, term := range q.terms {
			if searchNameContainsTerm(name, term) {
				df[term]++
			}
		}
	}
	total := float64(len(candidates))
	weights := make(map[string]float64, len(df)+1)
	ordered := make([]float64, 0, len(df))
	for term, n := range df {
		if n == 0 {
			continue
		}
		w := math.Log(1 + (total-float64(n)+0.5)/(float64(n)+0.5))
		weights[term] = w
		ordered = append(ordered, w)
	}
	if len(weights) == 0 {
		return nil
	}
	sort.Sort(sort.Reverse(sort.Float64Slice(ordered)))
	norm := 0.0
	for i := 0; i < len(ordered) && i < 3; i++ {
		norm += ordered[i]
	}
	weights[searchNameIDFNormKey] = norm
	return weights
}

