func completeBodyValue(plan []SearchResult) float64 {
	value := 0.0
	for index, result := range plan {
		if hasSearchSignal(result, searchCompleteSymbolSignal) {
			value += searchBodySlotWorth(result) / float64(index+1)
		}
	}
	return value
}

// searchBodySlotWorth discounts a body slot spent on something that is not editable code.
//
// A "complete body" is the payload's most expensive real estate and its entire promise is "you can
// edit from this without opening the file". For a one-line declaration that promise is empty: the
// body IS the locator, so completing it buys nothing while consuming the budget a real fix site
// needed.
//
// Measured on apache/druid-14092 (+32% vs its own baseline). The query
// "DruidLeaderClient should refresh cache for non-200 responses" put
// `private final DruidLeaderClient druidLeaderClient;` — the same one-line field in nine different
// files — at ranks 1, 2 and 4-10. BOTH body slots went to two of those one-liners, and the actual
// fix site (`DruidLeaderClient.java`, rank 3) was demoted to a bare locator with no code at all.
// Across the same 10-instance set, instances whose fix site got a real body averaged +2.3% while
// instances whose fix site got locator-only averaged +26.7% — a 24-point gap, and the largest
// actionable signal in that data.
//
// This is a value discount rather than a hard exclusion, deliberately. A declaration IS the fix site
// for definition-lookup intent (a query about a constant's value, an enum member, a struct field's
// type), and the allocator must still be able to complete one when nothing else competes for the
// budget. Ranking it below any real callable is enough; banning it would break that case.
func searchBodySlotWorth(result SearchResult) float64 {
	if searchKindClass(result.Kind) != searchKindData {
		return 1
	}
	if result.EndLine-result.StartLine > 2 {
		// A multi-line data declaration (a struct literal, a const block, a table) has content a
		// locator would not show, so its body slot is doing real work.
		return 1
	}
	if searchResultHasSignal(result, "exact-symbol") {
		// The query named this declaration outright — definition-lookup intent, it is the target.
		return 1
	}
	return 0.05
}

