#!/usr/bin/env python3
"""Paired cell scorer: geomean of per-instance ratios + bootstrap CI, per-language split.

Gate (applied SYMMETRICALLY): total_cost_usd > 0 AND non-empty patch.diff in BOTH arms,
else the instance leaves both arms. A cheap gate-failure would otherwise read as a saving.

Tokens = input + cache_creation + cache_read + output. Cost classes are reported separately
because the aggregate usd hides which class moved, and which class moved is the finding.
"""
import json, glob, os, math, random, sys, re

random.seed(20260803)

LANG = {
    'apache__lucene': 'Java', 'projectlombok__lombok': 'Java',
    'astral-sh__ruff': 'Rust', 'nushell__nushell': 'Rust',
    'briannesbitt__carbon': 'PHP', 'laravel__framework': 'PHP',
    'phpoffice__phpspreadsheet': 'PHP',
    'caddyserver__caddy': 'Go', 'gohugoio__hugo': 'Go',
    'hashicorp__terraform': 'Go',
    'django__django': 'Python', 'pylint-dev__pylint': 'Python',
    'scikit-learn__scikit-learn': 'Python', 'micropython__micropython': 'C',
    'fmtlib__fmt': 'C++', 'redis__redis': 'C',
    'faker-ruby__faker': 'Ruby', 'rubocop__rubocop': 'Ruby',
    'preactjs__preact': 'JS/TS', 'vuejs__core': 'JS/TS',
}


def lang_of(inst):
    for k, v in LANG.items():
        if inst.startswith(k):
            return v
    return '?'


def load(tag, arm):
    out = {}
    for d in glob.glob(f'results/{tag}/{arm}/*/'):
        inst = os.path.basename(d.rstrip('/'))
        cc, pd = f'{d}cc_out.json', f'{d}patch.diff'
        if not (os.path.exists(cc) and os.path.exists(pd)):
            continue
        if os.path.getsize(pd) == 0:
            continue
        try:
            j = json.load(open(cc))
        except Exception:
            continue
        usd = j.get('total_cost_usd') or 0
        if usd <= 0:
            continue
        u = j.get('usage', {}) or {}
        cr = u.get('cache_read_input_tokens', 0) or 0
        cc_t = u.get('cache_creation_input_tokens', 0) or 0
        it = u.get('input_tokens', 0) or 0
        ot = u.get('output_tokens', 0) or 0
        out[inst] = dict(usd=usd, tot=it + cc_t + cr + ot, cr=cr, cc=cc_t, out=ot,
                         turns=j.get('num_turns', 0), subtype=j.get('subtype', ''))
    return out


def geo(rs):
    return math.exp(sum(math.log(r) for r in rs) / len(rs)) - 1 if rs else float('nan')


def boot(rs, n=4000):
    if len(rs) < 3:
        return (float('nan'), float('nan'))
    gs = []
    for _ in range(n):
        s = [random.choice(rs) for _ in rs]
        gs.append(geo(s))
    gs.sort()
    return (gs[int(.025 * n)] * 100, gs[int(.975 * n)] * 100)


def cell(btag, etag, label, verbose=True):
    b, e = load(btag, 'baseline'), load(etag, 'eg')
    inst = sorted(set(b) & set(e))
    if not inst:
        print(f'{label}: NO GATED PAIRS (base {len(b)}, eg {len(e)})')
        return None
    res = {}
    for metric in ('tot', 'usd', 'cr', 'cc', 'out'):
        rs = [e[i][metric] / b[i][metric] for i in inst if b[i][metric] > 0]
        res[metric] = (geo(rs) * 100, boot(rs))
    if verbose:
        print(f'\n=== {label}  n={len(inst)} pairs '
              f'(submitted base {len(glob.glob(f"results/{btag}/baseline/*/"))}, '
              f'eg {len(glob.glob(f"results/{etag}/eg/*/"))}) ===')
        for m, nm in (('tot', 'TOKENS'), ('usd', 'usd'), ('cr', 'cache_read'),
                      ('cc', 'cache_creation'), ('out', 'output')):
            g, (lo, hi) = res[m]
            print(f'  {nm:<15} {g:+7.1f}%   CI [{lo:+6.1f}, {hi:+6.1f}]')
        wins = sum(1 for i in inst if e[i]['tot'] < b[i]['tot'])
        print(f'  winners: {wins}/{len(inst)}')
        by = {}
        for i in inst:
            by.setdefault(lang_of(i), []).append(e[i]['tot'] / b[i]['tot'])
        print('  per-language TOKENS:')
        for L in sorted(by, key=lambda k: geo(by[k])):
            print(f'    {L:<8} n={len(by[L])}  {geo(by[L])*100:+7.1f}%')
    res['n'] = len(inst)
    res['inst'] = inst
    res['b'] = b
    res['e'] = e
    return res


if __name__ == '__main__':
    for spec in sys.argv[1:]:
        btag, etag, label = spec.split(',')
        cell(btag, etag, label)

