    for p in per:
        cls='w' if p['r']<0 else 'l'
        o.append(f'''<tr class="{cls}"><td class="inst">{p['short']}</td><td class="lang"><span class="chip">{p['lang']}</span></td>
<td class="num">{p['bk']:,}k</td><td class="num">{p['ek']:,}k</td>
<td class="viz"><span class="track">{bar(p['r'])}</span></td><td class="num sig">{p['r']:+.0f}%</td></tr>''')
    return '\n'.join(o)
def grouprows(g):
    return '\n'.join(f'''<tr class="{'w' if x['g']<0 else 'l'}"><td class="inst">{x['k']}</td><td class="num dim">{x['n']}</td>
<td class="viz"><span class="track">{bar(x['g'])}</span></td><td class="num sig">{x['g']:+.0f}%</td></tr>''' for x in g)
